#define _GNU_SOURCE
#define _POSIX_C_SOURCE 200809L
#include "deadlocklab.h"
#include <arpa/inet.h>
#include <ctype.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

#define REQUEST_LIMIT 262144
#define RESPONSE_LIMIT 262144

static const char *skip(const char *p){while(*p&&isspace((unsigned char)*p))p++;return p;}
static const char *field(const char *json,const char *name){char key[96];snprintf(key,sizeof key,"\"%s\"",name);const char*p=json;while((p=strstr(p,key))){const char*before=p;while(before>json&&isspace((unsigned char)before[-1]))before--;if(before>json&&(before[-1]=='{'||before[-1]==',')){const char*q=skip(p+strlen(key));if(*q==':')return skip(q+1);}p+=strlen(key);}return NULL;}
static bool string_value(const char*p,char*out,size_t cap){if(!p||*p!='"'||cap<1)return false;p++;size_t n=0;while(*p&&*p!='"'){if(*p=='\\'&&p[1])p++;if(n+1>=cap)return false;out[n++]=*p++;}if(*p!='"')return false;out[n]=0;return true;}
static bool string_field(const char*j,const char*k,char*out,size_t cap){return string_value(field(j,k),out,cap);}
static bool string_array(const char*j,const char*k,char(*out)[DL_ID_LENGTH],size_t cap,size_t*count){const char*p=field(j,k);if(!p||*p!='[')return false;p++;*count=0;while(*(p=skip(p))&&*p!=']'){if(*count>=cap||!string_value(p,out[*count],DL_ID_LENGTH))return false;(*count)++;p=strchr(p,'"')+1;while(*p&&*p!='"'){if(*p=='\\'&&p[1])p++;p++;}if(*p!='"')return false;p++;p=skip(p);if(*p==','){p++;continue;}if(*p!=']')return false;}return *p==']';}
static bool int_array(const char*j,const char*k,int*out,size_t expected){const char*p=field(j,k);if(!p||*p!='[')return false;p++;size_t n=0;while(*(p=skip(p))&&*p!=']'){if(n>=expected)return false;char*end;long v=strtol(p,&end,10);if(end==p||v<0||v>2147483647L)return false;out[n++]=(int)v;p=skip(end);if(*p==','){p++;continue;}if(*p!=']')return false;}return *p==']'&&n==expected;}
static bool bool_array(const char*j,const char*k,bool*out,size_t expected){const char*p=field(j,k);if(!p||*p!='[')return false;p++;size_t n=0;while(*(p=skip(p))&&*p!=']'){if(n>=expected)return false;if(!strncmp(p,"true",4)){out[n++]=true;p+=4;}else if(!strncmp(p,"false",5)){out[n++]=false;p+=5;}else return false;p=skip(p);if(*p==','){p++;continue;}if(*p!=']')return false;}return *p==']'&&n==expected;}
static bool matrix_array(const char*j,const char*k,int out[DL_MAX_PROCESSES][DL_MAX_RESOURCES],size_t rows,size_t cols){const char*p=field(j,k);if(!p||*p!='[')return false;p++;size_t i=0;while(*(p=skip(p))&&*p!=']'){if(i>=rows||*p!='[')return false;p++;size_t c=0;while(*(p=skip(p))&&*p!=']'){if(c>=cols)return false;char*end;long v=strtol(p,&end,10);if(end==p||v<0||v>2147483647L)return false;out[i][c++]=(int)v;p=skip(end);if(*p==','){p++;continue;}if(*p!=']')return false;}if(*p!=']'||c!=cols)return false;p++;i++;p=skip(p);if(*p==','){p++;continue;}if(*p!=']')return false;}return *p==']'&&i==rows;}
static bool scenario_json(const char*j,DlScenario*s){memset(s,0,sizeof *s);if(!string_field(j,"id",s->id,sizeof s->id))return false;if(!string_array(j,"processes",s->processes,DL_MAX_PROCESSES,&s->process_count)||!string_array(j,"resources",s->resources,DL_MAX_RESOURCES,&s->resource_count))return false;if(!int_array(j,"total",s->total,s->resource_count)||!int_array(j,"available",s->available,s->resource_count)||!bool_array(j,"preemptible",s->preemptible,s->resource_count)||!matrix_array(j,"allocation",s->allocation,s->process_count,s->resource_count)||!matrix_array(j,"request",s->request,s->process_count,s->resource_count))return false;char ended[DL_MAX_PROCESSES][DL_ID_LENGTH];size_t n=0;if(!string_array(j,"terminated",ended,DL_MAX_PROCESSES,&n))return false;for(size_t k=0;k<n;k++){bool found=false;for(size_t i=0;i<s->process_count;i++)if(!strcmp(ended[k],s->processes[i])){if(s->terminated[i])return false;s->terminated[i]=true;found=true;}if(!found)return false;}return dl_validate(s).ok;}
static void append(char*b,size_t cap,size_t*used,const char*fmt,...){if(*used>=cap)return;va_list ap;va_start(ap,fmt);int n=vsnprintf(b+*used,cap-*used,fmt,ap);va_end(ap);if(n>0)*used+=(size_t)n<cap-*used?(size_t)n:cap-*used;}
static void vector(char*b,size_t cap,size_t*u,const int*v,size_t n){append(b,cap,u,"[");for(size_t i=0;i<n;i++)append(b,cap,u,"%s%d",i?",":"",v[i]);append(b,cap,u,"]");}
static void scenario_json_out(char*b,size_t cap,size_t*u,const DlScenario*s){append(b,cap,u,"{\"id\":\"%s\",\"processes\":[",s->id);for(size_t i=0;i<s->process_count;i++)append(b,cap,u,"%s\"%s\"",i?",":"",s->processes[i]);append(b,cap,u,"],\"resources\":[");for(size_t j=0;j<s->resource_count;j++)append(b,cap,u,"%s\"%s\"",j?",":"",s->resources[j]);append(b,cap,u,"],\"total\":");vector(b,cap,u,s->total,s->resource_count);append(b,cap,u,",\"available\":");vector(b,cap,u,s->available,s->resource_count);append(b,cap,u,",\"allocation\":[");for(size_t i=0;i<s->process_count;i++){if(i)append(b,cap,u,",");vector(b,cap,u,s->allocation[i],s->resource_count);}append(b,cap,u,"],\"request\":[");for(size_t i=0;i<s->process_count;i++){if(i)append(b,cap,u,",");vector(b,cap,u,s->request[i],s->resource_count);}append(b,cap,u,"],\"preemptible\":[");for(size_t j=0;j<s->resource_count;j++)append(b,cap,u,"%s%s",j?",":"",s->preemptible[j]?"true":"false");append(b,cap,u,"],\"terminated\":[");bool first=true;for(size_t i=0;i<s->process_count;i++)if(s->terminated[i]){append(b,cap,u,"%s\"%s\"",first?"":",",s->processes[i]);first=false;}append(b,cap,u,"]}");}
static void detection_json(char*b,size_t cap,size_t*u,const DlScenario*s,const DlDetection*d){append(b,cap,u,"{\"deadlocked\":[");for(size_t i=0;i<d->deadlocked_count;i++)append(b,cap,u,"%s\"%s\"",i?",":"",s->processes[d->deadlocked[i]]);append(b,cap,u,"],\"trace\":[");for(size_t i=0;i<d->trace_count;i++){const DlStep*t=&d->trace[i];if(i)append(b,cap,u,",");append(b,cap,u,"{\"process\":\"%s\",\"workBefore\":",s->processes[t->process_index]);vector(b,cap,u,t->work_before,s->resource_count);append(b,cap,u,",\"request\":");vector(b,cap,u,s->request[t->process_index],s->resource_count);append(b,cap,u,",\"componentFits\":[");for(size_t j=0;j<s->resource_count;j++)append(b,cap,u,"%s%s",j?",":"",t->component_fits[j]?"true":"false");append(b,cap,u,"],\"eligible\":%s,\"releasedAllocation\":",t->eligible?"true":"false");vector(b,cap,u,t->released,s->resource_count);append(b,cap,u,",\"workAfter\":");vector(b,cap,u,t->work_after,s->resource_count);append(b,cap,u,",\"decision\":\"%s\"}",t->eligible?"eligible; simulate completion":"request exceeds Work; remains unfinished");}append(b,cap,u,"],\"finalWork\":");vector(b,cap,u,d->final_work,s->resource_count);append(b,cap,u,"}");}
static void response(int fd,int status,const char*body){char h[512];const char*label=status==200?"OK":status==400?"Bad Request":status==404?"Not Found":"Internal Server Error";int n=snprintf(h,sizeof h,"HTTP/1.1 %d %s\r\nContent-Type: application/json; charset=utf-8\r\nAccess-Control-Allow-Origin: http://localhost:5173\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nConnection: close\r\nContent-Length: %zu\r\n\r\n",status,label,strlen(body));send(fd,h,(size_t)n,0);send(fd,body,strlen(body),0);}
static void handle(int fd,char*req){char method[8]={0},path[256]={0};sscanf(req,"%7s %255s",method,path);char*out=calloc(RESPONSE_LIMIT,1);if(!out){response(fd,500,"{\"error\":\"internal_error\"}");return;}size_t used=0;
 if(!strcmp(method,"OPTIONS")){response(fd,200,"{}");free(out);return;}
 if(!strcmp(method,"GET")&&!strcmp(path,"/api/health")){strcpy(out,"{\"status\":\"ok\",\"version\":\"1.0.0\",\"runtime\":\"C17/POSIX\"}");response(fd,200,out);free(out);return;}
 if(!strcmp(method,"GET")&&!strcmp(path,"/api/scenarios")){append(out,RESPONSE_LIMIT,&used,"[");for(size_t i=0;dl_fixture_ids(i);i++){DlScenario s;dl_fixture(dl_fixture_ids(i),&s);if(i)append(out,RESPONSE_LIMIT,&used,",");scenario_json_out(out,RESPONSE_LIMIT,&used,&s);}append(out,RESPONSE_LIMIT,&used,"]");response(fd,200,out);free(out);return;}
 if(!strcmp(method,"GET")&&!strncmp(path,"/api/scenarios/",15)){const char*id=path+15;bool found=false;for(size_t i=0;dl_fixture_ids(i);i++)if(!strcmp(id,dl_fixture_ids(i))){DlScenario s;dl_fixture(id,&s);scenario_json_out(out,RESPONSE_LIMIT,&used,&s);found=true;break;}response(fd,found?200:404,found?out:"{\"error\":\"not_found\",\"message\":\"scenario not found\"}");free(out);return;}
 char*body=strstr(req,"\r\n\r\n");body=body?body+4:NULL;DlScenario s;DlDetection d;DlValidation v;
 if((!strcmp(method,"POST")&&!strcmp(path,"/api/detect"))||(!strcmp(method,"POST")&&!strcmp(path,"/api/recover"))){if(!body||!scenario_json(body,&s)){response(fd,400,"{\"error\":\"validation_error\",\"message\":\"Invalid scenario JSON or invariant violation\"}");free(out);return;}
  if(!strcmp(path,"/api/recover")){char action[32],victim[DL_ID_LENGTH],resource[DL_ID_LENGTH];if(!string_field(body,"action",action,sizeof action)||!string_field(body,"process",victim,sizeof victim)){response(fd,400,"{\"error\":\"validation_error\",\"message\":\"Recovery action and process are required\"}");free(out);return;}size_t pi=s.process_count,rj=s.resource_count;for(size_t i=0;i<s.process_count;i++)if(!strcmp(victim,s.processes[i]))pi=i;if(!strcmp(action,"terminate"))v=dl_recover_terminate(&s,pi,&s);else if(!strcmp(action,"preempt")&&string_field(body,"resource",resource,sizeof resource)){for(size_t j=0;j<s.resource_count;j++)if(!strcmp(resource,s.resources[j]))rj=j;v=dl_recover_preempt(&s,pi,rj,&s);}else v=(DlValidation){.ok=false,.message="Unsupported recovery action"};if(!v.ok){append(out,RESPONSE_LIMIT,&used,"{\"error\":\"validation_error\",\"message\":\"%s\"}",v.message);response(fd,400,out);free(out);return;}}
  v=dl_detect(&s,&d);if(!v.ok){response(fd,400,"{\"error\":\"validation_error\",\"message\":\"Detection failed validation\"}");free(out);return;}if(!strcmp(path,"/api/recover")){append(out,RESPONSE_LIMIT,&used,"{\"scenario\":");scenario_json_out(out,RESPONSE_LIMIT,&used,&s);append(out,RESPONSE_LIMIT,&used,",\"detection\":");detection_json(out,RESPONSE_LIMIT,&used,&s,&d);append(out,RESPONSE_LIMIT,&used,"}");}else detection_json(out,RESPONSE_LIMIT,&used,&s,&d);response(fd,200,out);free(out);return;}
 response(fd,404,"{\"error\":\"not_found\",\"message\":\"endpoint not found\"}");free(out);
}
int main(void){signal(SIGPIPE,SIG_IGN);int port=8080;const char*env=getenv("PORT");if(env){int p=atoi(env);if(p>0&&p<65536)port=p;}int server=socket(AF_INET,SOCK_STREAM,0);if(server<0){perror("socket");return 1;}int yes=1;setsockopt(server,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof yes);struct sockaddr_in addr={.sin_family=AF_INET,.sin_addr.s_addr=htonl(INADDR_ANY),.sin_port=htons((unsigned short)port)};if(bind(server,(struct sockaddr*)&addr,sizeof addr)||listen(server,32)){perror("bind/listen");close(server);return 1;}printf("DeadlockLab C API listening on http://0.0.0.0:%d\n",port);fflush(stdout);for(;;){int fd=accept(server,NULL,NULL);if(fd<0)continue;char*req=calloc(REQUEST_LIMIT+1,1);if(req){size_t n=0;while(n<REQUEST_LIMIT){ssize_t got=recv(fd,req+n,REQUEST_LIMIT-n,0);if(got<=0)break;n+=(size_t)got;req[n]=0;char*end=strstr(req,"\r\n\r\n");if(end){size_t head=(size_t)(end+4-req);char*cl=strcasestr(req,"Content-Length:");size_t expected=0;if(cl&&cl<end)expected=(size_t)strtoul(cl+15,NULL,10);if(n>=head+expected)break;}}handle(fd,req);free(req);}close(fd);}close(server);return 0;}
